/**
 * The frozen `data-testid` contract for `/admin/coord/questions`, as it
 * actually reaches the DOM.
 *
 * Added by plan `2026-08-16-coord-console-ui-unification-pipeline-style.md`
 * Phase 3 Wave 1. `tests/e2e/pages/admin-coord-questions.spec.ts` asserts
 * `coord-questions-page`, `coord-questions-tab-pending`,
 * `coord-questions-tab-answered` and `coord-questions-pending-count`, and this
 * migration replaced the elements all four used to sit on:
 *
 *   - the two tab testids are now GENERATED by `<FilterTabs>` from
 *     `testIdPrefix` + the tab id, so no grep of this route's source can prove
 *     they still exist — only a render can;
 *   - `coord-questions-pending-count` moved from a `<CardTitle>` badge onto the
 *     health strip's pending badge.
 *
 * A Playwright suite that reds two hours into CI is a worse way to learn a
 * testid was dropped than a unit test that reds in two seconds, which is why
 * this file exists at all.
 */

import { describe, expect, it, vi, beforeEach } from "vitest";
import {
  render,
  screen,
  waitFor,
  act,
  fireEvent,
} from "@testing-library/react";
import userEvent from "@testing-library/user-event";

const POLL_INTERVAL_MS = 10_000;

const get = vi.fn();

/**
 * Did SOME `get` call request this URL fragment?
 *
 * Deliberately NOT `expect(get).toHaveBeenCalledWith(stringContaining(...))`:
 * that matcher pins the call's WHOLE argument list, and a POLLED read carries a
 * second argument — `COORD_DASHBOARD_POLL_OPTIONS` (`{maxRetries: 0}`), so one
 * slow coord read is not multiplied by the client's retry chain. A correct URL
 * therefore fails a one-argument matcher, which is a test asserting the calling
 * convention while claiming to assert the URL. This reads the URL alone, so the
 * assertion survives any future change to the options argument.
 */
const requestedUrl = (fragment: string): boolean =>
  get.mock.calls.some((c) => String(c[0]).includes(fragment));

/**
 * Did SOME `get` call carry this query PARAMETER, exactly?
 *
 * Substring matching is not good enough for numbers: `includes("offset=50")`
 * also matches `offset=500`. Anchoring with a trailing `&` only works while a
 * following parameter happens to exist — which stops being true the moment the
 * audience filter is cleared. Parsing the query string is exact, order-free and
 * immune to both.
 */
const requestedParam = (name: string, value: string): boolean =>
  get.mock.calls.some((c) => {
    const q = String(c[0]).split("?")[1];
    return q !== undefined && new URLSearchParams(q).get(name) === value;
  });

vi.mock("@/services/service-factory", () => ({
  httpClient: {
    get: (...args: unknown[]) => get(...args),
    post: vi.fn(),
  },
}));

/**
 * `GapRow` calls `useAuth`, so rendering a real one needs an `AuthProvider`
 * this suite has no reason to stand up — every pre-existing gap test asserts
 * an EMPTY gap list and so never reached the row. The gap-queue tests below
 * serve 200 rows to drive the truncation verdict, which does. The row's own
 * behaviour is not what any test here is about; the counts and notices derived
 * from the list are.
 */
vi.mock("@/components/admin/coord/GapRow", () => ({
  GapRow: ({ question }: { question: { question_id: string } }) => (
    <div data-testid="coord-gap-row">{question.question_id}</div>
  ),
}));

import CoordQuestionsPage from "./page";

const PENDING = [
  {
    question_id: "00000000-0000-0000-0000-deadbeef0001",
    agent_id: "01a01de1-9d08-7c31-a055-271ad6df6217",
    question: "Bump or pin the dependency?",
    created_at: "2026-08-20T09:00:00Z",
  },
];

/** A POLICY_GAP question that has ALREADY been answered — a gap, not blocking. */
const ANSWERED_GAP = {
  question_id: "00000000-0000-0000-0000-deadbeef0002",
  agent_id: "01a01de1-9d08-7c31-a055-271ad6df6217",
  question: "POLICY_GAP: no clause covers a dependency bump",
  created_at: "2026-08-20T08:00:00Z",
  responded_at: "2026-08-20T08:30:00Z",
  response: "added a clause",
  // `isGapQuestion` keys on this marker, not on the question text — without
  // it the row is filtered out and the scenario silently collapses to the
  // empty-list case the other tests already cover.
  context:
    'POLICY_GAP {"policy_gap":{"category":"dependencies"},"context":null}',
};

beforeEach(() => {
  get.mockReset();
  get.mockImplementation(async (url: string) => {
    if (url.includes("gap=true")) return { questions: [] };
    if (url.includes("/pending")) return { questions: PENDING };
    return { questions: [] };
  });
});

describe("/admin/coord/questions frozen testids (D4a)", () => {
  it("emits every testid the Playwright suite asserts", async () => {
    render(<CoordQuestionsPage />);

    expect(screen.getByTestId("coord-questions-page")).toBeInTheDocument();

    await waitFor(() => {
      expect(
        screen.getByTestId("coord-questions-pending-count")
      ).toBeInTheDocument();
    });

    // Generated by <FilterTabs> from testIdPrefix — the strings that matter.
    expect(
      screen.getByTestId("coord-questions-tab-pending")
    ).toBeInTheDocument();
    expect(
      screen.getByTestId("coord-questions-tab-answered")
    ).toBeInTheDocument();
    expect(screen.getByTestId("coord-questions-tab-gaps")).toBeInTheDocument();

    expect(screen.getByTestId("coord-questions-tabs")).toBeInTheDocument();
    expect(screen.getByTestId("coord-questions-refresh")).toBeInTheDocument();
    expect(
      screen.getByTestId("coord-questions-pending-list")
    ).toBeInTheDocument();
  });

  it("counts the pending inbox rather than claiming zero before it arrives", async () => {
    render(<CoordQuestionsPage />);
    // First paint: the fetch is in flight, so the badge reads the dash.
    expect(
      screen.getByTestId("coord-questions-pending-count")
    ).toHaveTextContent("–");
    await waitFor(() => {
      expect(
        screen.getByTestId("coord-questions-pending-count")
      ).toHaveTextContent("1 pending");
    });
    expect(screen.getByTestId("coord-question-card")).toBeInTheDocument();
  });
});

/**
 * A read that FAILED must render as unknown, never as zero/none.
 *
 * `fetchAnswered` and `fetchGaps` both swallowed their errors into a
 * `console.warn`, leaving their lists at the `[]` the `useState` initializer
 * had put there — the identical array a successful empty read produces. Every
 * consumer downstream then stated the absence as fact, and the worst of them
 * was the health strip: `blockingGaps === 0` and `pending.length === 0` is the
 * GREEN arm, headline **"No agent is waiting on an answer"**. Coord going dark
 * rendered as the all-clear, which is the one sentence that tells an operator
 * to stop looking at this page.
 *
 * Each test below asserts the LITERAL copy an operator would read, in both
 * directions: the unknown marker is present AND the absence claim is gone. A
 * build that rendered both would still be making the false claim.
 */
describe("/admin/coord/questions — a failed read is unknown, not empty", () => {
  /** Fail exactly the URLs matching `failOn`; serve empty for the rest. */
  function routeWithFailures(failOn: RegExp) {
    get.mockImplementation(async (url: string) => {
      if (failOn.test(url)) throw new Error("coord unreachable");
      return { questions: [] };
    });
  }

  it("does not report the all-clear when the gap inbox could not be read", async () => {
    routeWithFailures(/gap=true/);
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    await waitFor(() => expect(strip).toHaveTextContent(/could not read/i));
    // The precise sentence that would send an operator away.
    expect(strip.textContent ?? "").not.toMatch(
      /No agent is waiting on an answer/i
    );
    expect(strip).toHaveTextContent(/unknown/i);
    // The DOT, not just the words. The pulsing traffic light is what an
    // operator scans; a regression that reverted only the `level` expression
    // while keeping the new headline would pass every copy assertion here and
    // still show green on an inbox nobody read.
    expect(strip).toHaveAttribute("data-health-level", "amber");
    // The count is a dash, not a zero it never measured.
    expect(strip).toHaveTextContent(/gaps\s*–/);
    expect(strip.textContent ?? "").not.toMatch(/gaps\s*0/);
  });

  it("does not go green when a gap read that HAD landed then failed", async () => {
    // The narrow window the first cut of this fix missed: the gap list unions
    // `pending?gap=true` with `answered?gap=true`, so a retained list can be
    // NON-empty while `blockingGaps` is 0 — every row already answered.
    //
    // The predicates are now keyed on whether the READ landed (`readIsUnknown`)
    // rather than on the count each surface renders, so this scenario moved
    // from UNKNOWN to STALE — coord did answer, and its answer was "one gap,
    // already answered". The count therefore SURVIVES as `gaps 0` instead of
    // dashing, and the detail line labels it as the last one that landed.
    //
    // What must NOT change is the dot and the headline. A stale verdict is not
    // a green verdict: `gaps 0` is a measurement, while green is a claim about
    // now, and nobody has read now. This test is the pin on that distinction —
    // the count relaxes, the all-clear does not.
    let gapCalls = 0;
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) {
        gapCalls += 1;
        if (gapCalls > 2) throw new Error("coord unreachable");
        // Two reads make up one `fetchGaps`; put the answered gap on the
        // answered leg so the first load succeeds with a non-blocking gap.
        return url.includes("/answered")
          ? { questions: [ANSWERED_GAP] }
          : { questions: [] };
      }
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    // First load lands: one gap, none blocking — genuinely green.
    await waitFor(() =>
      expect(strip).toHaveAttribute("data-health-level", "green")
    );
    expect(strip).toHaveTextContent(/gaps\s*0/);

    // Now coord goes dark and the operator refreshes.
    await user.click(screen.getByTestId("coord-questions-refresh"));

    await waitFor(() =>
      expect(strip).toHaveAttribute("data-health-level", "amber")
    );
    expect(strip.textContent ?? "").not.toMatch(
      /No agent is waiting on an answer/i
    );
    // The stale headline names the READ that has not come back, and stops
    // there. It deliberately does not say what was waiting at the last good
    // read: `blockingGaps` counts `visibleGaps`, which `handledGaps` filters
    // optimistically, so that sentence could be false about the read it names.
    expect(strip).toHaveTextContent(
      /gaps inbox has not refreshed since the last good read/i
    );
    expect(strip).toHaveTextContent(/not clear, just not re-read/i);
    // The count coord DID answer survives, named as stale rather than dashed.
    expect(strip).toHaveTextContent(/gaps\s*0/);
    expect(strip).toHaveTextContent(/Last refresh failed for: gaps/);
    expect(strip.textContent ?? "").not.toMatch(/gaps\s*–/);
  });

  it("does not dash a count coord confirmed EMPTY when a later poll fails", async () => {
    // The flicker the older `readFailed && count === 0` spelling produced. An
    // inbox coord has answered as empty is indistinguishable from one that
    // never arrived if the predicate keys on the count, so one blipped poll
    // flipped this page from "No pending questions" to "could not be read" and
    // back on the next tick — off no new information at all. Keyed on
    // `loaded`, the empty answer holds and the failure reads as stale.
    let pendingCalls = 0;
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending")) {
        pendingCalls += 1;
        if (pendingCalls > 1) throw new Error("coord unreachable");
        return { questions: [] };
      }
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    await waitFor(() =>
      expect(strip).toHaveAttribute("data-health-level", "green")
    );

    await user.click(screen.getByTestId("coord-questions-refresh"));

    // The count coord confirmed is kept, and named as no longer current.
    await waitFor(() =>
      expect(strip).toHaveTextContent(/Last refresh failed for: pending/)
    );
    expect(strip).toHaveTextContent(/0\s*pending/);
    expect(strip.textContent ?? "").not.toMatch(/–\s*pending/);
    // The list keeps coord's answer rather than claiming it is unreadable —
    // and dates it. The bare "No pending questions." would be a present-tense
    // claim off a read that is currently failing, which is the same
    // over-claim as the green dot, one element down.
    const stale = screen.getByTestId("coord-questions-pending-stale");
    expect(stale).toHaveTextContent(/as of the last good read/i);
    expect(
      screen.queryByTestId("coord-questions-pending-unreadable")
    ).toBeNull();
    expect(screen.queryByTestId("coord-questions-pending-empty")).toBeNull();
    // …and the verdict still steps down, because stale is not current.
    expect(strip).toHaveAttribute("data-health-level", "amber");
    expect(strip.textContent ?? "").not.toMatch(
      /No agent is waiting on an answer/i
    );
  });

  it("reports an unknown read and a stale one in the same detail line", async () => {
    // The previous `anyStale && !anyUnknown` form dropped the stale clause
    // entirely whenever anything was unknown, so a page with an unread pending
    // inbox said nothing about a gaps count that had quietly gone out of date.
    let gapCalls = 0;
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) {
        gapCalls += 1;
        // Two reads make one `fetchGaps`: the first lands, the rest fail.
        if (gapCalls > 2) throw new Error("coord unreachable");
        return { questions: [] };
      }
      // Pending never lands at all — unknown, not stale.
      if (url.includes("/pending")) throw new Error("coord unreachable");
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    await waitFor(() =>
      expect(strip).toHaveTextContent(/coord did not answer for: pending/)
    );
    await user.click(screen.getByTestId("coord-questions-refresh"));

    await waitFor(() =>
      expect(strip).toHaveTextContent(/Last refresh failed for: gaps/)
    );
    // Both clauses, at once — a read is in exactly one of the two lists.
    expect(strip).toHaveTextContent(/coord did not answer for: pending/);
    expect(strip).toHaveTextContent(/–\s*pending/);
    expect(strip).toHaveTextContent(/gaps\s*0/);
  });

  it("dashes the pending badge and every tab count that could not be read", async () => {
    // The badge/tab half of the fix, which the copy assertions do not reach.
    get.mockImplementation(async () => {
      throw new Error("coord unreachable");
    });
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    await waitFor(() =>
      expect(strip).toHaveAttribute("data-health-level", "amber")
    );
    expect(strip).toHaveTextContent(/–\s*pending/);
    expect(strip).toHaveTextContent(/gaps\s*–/);
    expect(strip).toHaveTextContent(/answered\s*–/);
    expect(strip.textContent ?? "").not.toMatch(/0\s*pending/);
    // All three named in the detail line, and the noun agrees.
    expect(strip).toHaveTextContent(/pending, gaps, answered/);
    expect(strip).toHaveTextContent(/inboxes/);

    for (const id of [
      "coord-questions-tab-pending",
      "coord-questions-tab-answered",
      "coord-questions-tab-gaps",
    ]) {
      expect(screen.getByTestId(id)).toHaveTextContent("–");
      expect(screen.getByTestId(id).textContent ?? "").not.toMatch(/\b0\b/);
    }
  });

  it("treats a 200 whose body has no `questions` array as unknown, not empty", async () => {
    // The same class with an HTTP 200 in front of it: `?? []` turned an
    // unrecognised shape into a confident zero.
    get.mockImplementation(async () => ({ unexpected: "shape" }));
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    await waitFor(() =>
      expect(strip).toHaveAttribute("data-health-level", "amber")
    );
    expect(strip.textContent ?? "").not.toMatch(
      /No agent is waiting on an answer/i
    );
  });

  it("leaves the strip green when only the ANSWERED read fails", async () => {
    // Over-correction guard. The strip answers "is an agent waiting?", which
    // pending + gaps decide on their own. `fetchAnswered`'s own comment says
    // the endpoint may not be wired on every coord build — letting it drive
    // the level would leave such a build permanently amber with the all-clear
    // permanently hidden, which teaches operators to ignore amber.
    routeWithFailures(/\/answered\?limit=/);
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    await waitFor(() =>
      expect(strip).toHaveTextContent(/No agent is waiting on an answer/i)
    );
    expect(strip).toHaveAttribute("data-health-level", "green");
    // Still surfaced, just not as the verdict: the badge dashes and the detail
    // line names it.
    expect(strip).toHaveTextContent(/answered\s*–/);
    expect(strip).toHaveTextContent(/coord did not answer for: answered/);
  });

  it("says the gap list is unreadable instead of 'No policy gaps reported'", async () => {
    routeWithFailures(/gap=true/);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await user.click(await screen.findByTestId("coord-questions-tab-gaps"));
    expect(
      await screen.findByTestId("coord-questions-gaps-unreadable")
    ).toHaveTextContent(/unknown/i);
    expect(screen.queryByTestId("coord-questions-gaps-empty")).toBeNull();
    expect(
      screen.getByTestId("coord-questions-gaps-list").textContent ?? ""
    ).not.toMatch(/No policy gaps reported/i);
  });

  it("says the answered list is unreadable instead of 'No recently-answered questions'", async () => {
    // Only the plain answered read fails — the `gap=true` variants still work,
    // so this pins the answered arm on its own rather than riding the gap one.
    routeWithFailures(/\/answered\?limit=/);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await user.click(await screen.findByTestId("coord-questions-tab-answered"));
    expect(
      await screen.findByTestId("coord-questions-answered-unreadable")
    ).toHaveTextContent(/unknown/i);
    expect(screen.queryByTestId("coord-questions-answered-empty")).toBeNull();
    expect(screen.getByTestId("coord-questions-health")).toHaveTextContent(
      /answered\s*–/
    );
  });

  it("dates the gaps and answered lists too when their reads go stale", async () => {
    // The two stale slots behind a tab click. Both lists answer once and then
    // go dark, so each falls in the STALE arm rather than the unknown one —
    // the plain copy would claim "No policy gaps reported." and "No
    // recently-answered questions." in the present tense off reads that are
    // currently failing.
    let gapCalls = 0;
    let answeredCalls = 0;
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) {
        gapCalls += 1;
        // Two reads make one `fetchGaps`; the first pair lands, the rest fail.
        if (gapCalls > 2) throw new Error("coord unreachable");
        return { questions: [] };
      }
      if (url.includes("/answered")) {
        answeredCalls += 1;
        if (answeredCalls > 1) throw new Error("coord unreachable");
        return { questions: [] };
      }
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await screen.findByTestId("coord-questions-health");
    await user.click(screen.getByTestId("coord-questions-refresh"));

    await user.click(screen.getByTestId("coord-questions-tab-gaps"));
    const gapsStale = await screen.findByTestId("coord-questions-gaps-stale");
    expect(gapsStale).toHaveTextContent(/not an all-clear/i);
    expect(screen.queryByTestId("coord-questions-gaps-empty")).toBeNull();
    expect(screen.queryByTestId("coord-questions-gaps-unreadable")).toBeNull();

    await user.click(screen.getByTestId("coord-questions-tab-answered"));
    const answeredStale = await screen.findByTestId(
      "coord-questions-answered-stale"
    );
    expect(answeredStale).toHaveTextContent(/as of the last good read/i);
    expect(screen.queryByTestId("coord-questions-answered-empty")).toBeNull();
    expect(
      screen.queryByTestId("coord-questions-answered-unreadable")
    ).toBeNull();
  });

  it("says the pending list is unreadable instead of 'No pending questions'", async () => {
    // `/pending?limit=…` — the plain pending read, NOT `/pending?gap=true`.
    // It used to be spelled `/\/pending$/`, which stopped matching when the
    // page began sending `limit`/`offset`/`audience`. Same convention as the
    // answered matcher above.
    routeWithFailures(/\/pending\?limit=/);
    render(<CoordQuestionsPage />);

    expect(
      await screen.findByTestId("coord-questions-pending-unreadable")
    ).toHaveTextContent(/unknown/i);
    expect(screen.queryByTestId("coord-questions-pending-empty")).toBeNull();
    const strip = screen.getByTestId("coord-questions-health");
    expect(strip.textContent ?? "").not.toMatch(
      /No agent is waiting on an answer/i
    );
  });

  it("still shows the all-clear when every read SUCCEEDS and is genuinely empty", async () => {
    // The other half of the pin: the unknown arms must not swallow the real
    // green state, or the fix would be indistinguishable from breaking it.
    get.mockImplementation(async () => ({ questions: [] }));
    render(<CoordQuestionsPage />);

    const strip = await screen.findByTestId("coord-questions-health");
    await waitFor(() =>
      expect(strip).toHaveTextContent(/No agent is waiting on an answer/i)
    );
    expect(strip).toHaveAttribute("data-health-level", "green");
    expect(strip.textContent ?? "").not.toMatch(/could not read/i);
    expect(strip).toHaveTextContent(/gaps\s*0/);
  });

  it("ignores a STALE successful gap read that lands after a newer one failed", async () => {
    // The race direction that fails UNSAFE, and the reason all three reads
    // carry a generation guard. A slow first read resolving late runs
    // `setGaps(merged); setGapsError(false)` \u2014 repainting the GREEN all-clear
    // on top of a read that is failing right now. That is this whole PR's
    // defect, re-created in a window the degraded poll makes ordinary.
    let gapCalls = 0;
    let releaseFirst!: () => void;
    const firstLanded = new Promise<void>((res) => {
      releaseFirst = res;
    });
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) {
        gapCalls += 1;
        // One `fetchGaps` issues TWO gap reads; the first pair hangs.
        if (gapCalls <= 2) {
          await firstLanded;
          return { questions: [] };
        }
        throw new Error("coord unreachable");
      }
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    // Refresh while the first gap read is still in flight: the SECOND read
    // fails, and it is the current one.
    await user.click(await screen.findByTestId("coord-questions-refresh"));
    const strip = screen.getByTestId("coord-questions-health");
    await waitFor(() =>
      expect(strip).toHaveAttribute("data-health-level", "amber")
    );
    expect(strip).toHaveTextContent(/could not read/i);

    // Now let the superseded, SUCCESSFUL read land. It must be dropped.
    releaseFirst();
    await new Promise((r) => setTimeout(r, 50));

    expect(strip).toHaveAttribute("data-health-level", "amber");
    expect(strip.textContent ?? "").not.toMatch(
      /No agent is waiting on an answer/i
    );
    expect(strip).toHaveTextContent(/gaps\s*\u2013/);
  });

  it("names which read went stale when a failure left a real count behind", async () => {
    // `anyStale` is the third state: the read failed, but the list it left is
    // non-empty, so nothing is fabricated \u2014 only out of date. Saying merely
    // "something is stale" sends an operator hunting, so it names the read.
    let calls = 0;
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending")) {
        calls += 1;
        if (calls > 1) throw new Error("coord unreachable");
        return { questions: PENDING };
      }
      return { questions: [] };
    });
    render(<CoordQuestionsPage />);
    await waitFor(() =>
      expect(
        screen.getByTestId("coord-questions-pending-count")
      ).toHaveTextContent("1 pending")
    );

    await userEvent
      .setup()
      .click(screen.getByTestId("coord-questions-refresh"));
    await screen.findByText(/Failed to load/i);

    const strip = screen.getByTestId("coord-questions-health");
    // The stale clause opens with its own verb now. It used to share the
    // unknown clause's "coord did not answer for:", which was serviceable
    // while only one of the two could render — the detail line now emits both
    // when both apply, and two sentences with the same opening would read as
    // one repeated claim rather than two different ones.
    expect(strip).toHaveTextContent(/Last refresh failed for: pending/);
    expect(strip).toHaveTextContent(/last ones that landed/);
    // Not the UNKNOWN copy \u2014 the count is real, just old.
    expect(strip.textContent ?? "").not.toMatch(/a dash, not a zero/);
  });

  it("keeps a stale-but-real count rather than blanking it when a POLL fails", async () => {
    // A failed read only fabricates when the list it left behind is EMPTY.
    // A retained non-empty list is stale, not invented, and blanking it would
    // discard a count the operator can still act on.
    let calls = 0;
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending")) {
        calls += 1;
        if (calls > 1) throw new Error("coord unreachable");
        return { questions: PENDING };
      }
      return { questions: [] };
    });
    render(<CoordQuestionsPage />);
    await waitFor(() =>
      expect(
        screen.getByTestId("coord-questions-pending-count")
      ).toHaveTextContent("1 pending")
    );

    await screen.findByTestId("coord-questions-refresh");
    await userEvent
      .setup()
      .click(screen.getByTestId("coord-questions-refresh"));

    // Wait on an OBSERVABLE consequence of the rejection, not on the request
    // counter: `calls` is bumped inside the mock before it throws, so it
    // proves only that the request went out — the assertion below would pass
    // vacuously if it ran before the catch had re-rendered.
    await screen.findByText(/Failed to load/i);
    expect(
      screen.getByTestId("coord-questions-pending-count")
    ).toHaveTextContent("1 pending");
    // And the verdict still reflects the count we can still act on.
    expect(screen.getByTestId("coord-questions-health")).toHaveAttribute(
      "data-health-level",
      "red"
    );
    expect(calls).toBeGreaterThan(1);
  });
});

/**
 * Reachability — plan
 * `2026-09-12-a-correctly-escalated-question-is-unreachable-in-the-operator-inbox`
 * Phase 2d.
 *
 * The measured defect: `coord.agent_questions` held ~23,700 pending rows,
 * 23,258 of them `pr_fix` addressed to an AGENT and only ~442 to the operator.
 * This page fetched pending with no `limit`, coord silently capped the result
 * at 100, and the page read none of the truncation fields coord already sends.
 * The operator saw 100 rows out of 23,700 with **nothing saying so**, and a
 * correctly-escalated security question was unanswerable for 10 days.
 *
 * Every test below is keyed on the WIRE names — `total` and `truncated`.
 * `total_matching` and `effective_limit` are coord's internal SQL-alias and
 * Rust field names and never reach the browser; a page reading those gets
 * `undefined` and renders exactly the defect above, which is why the fixtures
 * here deliberately carry only the serialized six.
 */
describe("/admin/coord/questions — the page states the size of the queue", () => {
  /**
   * Coord's envelope: `{questions, count, limit, shown, offset}` always, plus
   * `total` and `truncated` **only when coord could observe them**.
   *
   * The omission is the contract, not a fixture convenience. `total` comes from
   * `COUNT(*) OVER ()`, which rides on the returned rows — so a window past the
   * end of the match set has no row to carry it and coord leaves the KEY OUT
   * rather than sending a `0` every reader would take for a measurement.
   * `truncated` goes with it, because it is a claim about a match set this page
   * could not see. `omitTotal` is how a fixture reproduces that; `omitOffset`
   * reproduces a build that never learned the parameter.
   *
   * `truncated`'s default is coord's own offset-aware rule,
   * `total > offset + shown` — the rule the page must prefer over recomputing
   * one of its own.
   */
  function envelope(
    questions: unknown[],
    opts: {
      total?: number;
      truncated?: boolean;
      limit?: number;
      offset?: number;
      omitTotal?: boolean;
      omitOffset?: boolean;
    } = {}
  ) {
    const limit = opts.limit ?? 50;
    const offset = opts.offset ?? 0;
    const env: Record<string, unknown> = {
      questions,
      count: questions.length,
      limit,
      shown: questions.length,
    };
    if (!opts.omitOffset) env.offset = offset;
    if (!opts.omitTotal) {
      const total = opts.total ?? questions.length;
      env.total = total;
      env.truncated = opts.truncated ?? total > offset + questions.length;
    }
    return env;
  }

  function rows(n: number, from = 0, audience = "operator") {
    return Array.from({ length: n }, (_, i) => ({
      question_id: `00000000-0000-0000-0000-00000000${String(from + i).padStart(
        4,
        "0"
      )}`,
      agent_id: "01a01de1-9d08-7c31-a055-271ad6df6217",
      question: `pending question number ${from + i}`,
      created_at: "2026-09-12T09:00:00Z",
      audience,
    }));
  }

  const offsetOf = (url: string) =>
    Number(new URL(url, "http://x").searchParams.get("offset") ?? 0);

  /**
   * Serve `total` pending rows, behaving as coord does: honour `limit` and
   * `offset`, ECHO the offset back, and — for a window that lands past the end
   * of the match set — omit `total`/`truncated` entirely, because
   * `COUNT(*) OVER ()` had no row to ride on.
   *
   * `total` is read through a getter so a test can shrink the queue under a
   * page the operator is already holding, which is the measured shape of the
   * past-the-end failure.
   */
  function servePaged(
    total: number | (() => number),
    pageSize = 50,
    audience = "operator"
  ) {
    const totalNow = () => (typeof total === "function" ? total() : total);
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit=")) {
        const offset = offsetOf(url);
        const t = totalNow();
        const n = Math.max(0, Math.min(pageSize, t - offset));
        return envelope(rows(n, offset, audience), {
          total: t,
          limit: pageSize,
          offset,
          omitTotal: n === 0 && offset > 0,
        });
      }
      return { questions: [] };
    });
  }

  it("renders coord's own total, not the length of the page it was handed", async () => {
    // Three rows on the page, 23,700 in the queue. `pending.length` is 3 and
    // says nothing about the queue; `total` is an exact pre-LIMIT
    // `COUNT(*) OVER ()`, so it is rendered as the real number — never a
    // "100+" hedge, and never the page length.
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit="))
        return envelope(rows(3), { total: 23700, truncated: true });
      return { questions: [] };
    });
    render(<CoordQuestionsPage />);

    const badge = await screen.findByTestId("coord-questions-pending-count");
    await waitFor(() => expect(badge).toHaveTextContent("23,700 pending"));
    // The old rendering, explicitly absent: the page length as the count.
    expect(badge.textContent ?? "").not.toMatch(/(^|\D)3 pending/);

    // The headline an operator reads first carries the same number.
    const strip = screen.getByTestId("coord-questions-health");
    expect(strip).toHaveTextContent(/23,700 agents are stopped waiting on you/);
    // And the tab count (rendered raw by the `FilterTabs` primitive).
    expect(screen.getByTestId("coord-questions-tab-pending")).toHaveTextContent(
      "23700"
    );
  });

  it("says plainly that rows were dropped when coord reports truncation", async () => {
    // THE inversion target. Without this notice a full page is
    // indistinguishable from a complete queue, which is the entire defect.
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit="))
        return envelope(rows(3), { total: 23700, truncated: true });
      return { questions: [] };
    });
    render(<CoordQuestionsPage />);

    const notice = await screen.findByTestId(
      "coord-questions-pending-truncated"
    );
    // The range is the rows actually returned — not `offset + pageSize`.
    expect(notice).toHaveTextContent(/Showing 1–3 of 23,700 pending questions/);
    expect(notice).toHaveTextContent(/23,697 are not on this page/);
    // …and it names the filter that is narrowing the queue further.
    expect(notice).toHaveTextContent(/audience=operator/);
  });

  it("states truncation as UNKNOWN-sized when coord flags it without a total", async () => {
    // A build that sends `truncated` but no `total` knows rows were cut and
    // not how many. Claiming a number there would be inventing one; claiming
    // nothing would be the original defect.
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit="))
        return { questions: rows(2), truncated: true };
      return { questions: [] };
    });
    render(<CoordQuestionsPage />);

    const notice = await screen.findByTestId(
      "coord-questions-pending-truncated"
    );
    expect(notice).toHaveTextContent(/did not say how many rows it left out/i);
  });

  it("shows no truncation notice when the page IS the whole queue", async () => {
    // The other half of the pin: a notice that always renders proves nothing.
    servePaged(3);
    render(<CoordQuestionsPage />);

    await waitFor(() =>
      expect(
        screen.getByTestId("coord-questions-pending-count")
      ).toHaveTextContent("3 pending")
    );
    expect(
      screen.queryByTestId("coord-questions-pending-truncated")
    ).toBeNull();
    expect(screen.queryByTestId("coord-questions-pending-pager")).toBeNull();
  });

  it("pages by offset, and reports the range it is showing", async () => {
    servePaged(23700);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    const range = await screen.findByTestId("coord-questions-pending-range");
    expect(range).toHaveTextContent("1–50 of 23,700");
    expect(screen.getByTestId("coord-questions-pending-prev")).toBeDisabled();

    await user.click(screen.getByTestId("coord-questions-pending-next"));
    await waitFor(() => expect(requestedParam("offset", "50")).toBe(true));
    await waitFor(() => expect(range).toHaveTextContent("51–100 of 23,700"));
    expect(
      screen.getByTestId("coord-questions-pending-prev")
    ).not.toBeDisabled();
  });

  // The one thing about this page's POLLING that had no test at all. Main's
  // single-flight/no-retry fix (`COORD_DASHBOARD_POLL_OPTIONS`) converted every
  // read here, and its own invariant is "`polled` is true for reads the timer
  // issues" — but a past-end clamp issues its FOLLOW-UP through the paging
  // effect, which defaulted `polled` to false. So a clamp the TIMER caused went
  // out with the client's full retry chain and outside the single-flight latch:
  // the exact multiplication those options exist to remove. Main shipped no
  // polling test for this page and this suite had none, which is how it landed.
  it("keeps the no-retry posture when the TIMER's read clamps a past-end window", async () => {
    vi.useFakeTimers();
    try {
      let total = 23700;
      servePaged(() => total);
      render(<CoordQuestionsPage />);
      await act(async () => {
        await vi.advanceTimersByTimeAsync(0);
      });

      // Hold the last page, then let the queue shrink out from under it, so the
      // next read at that offset is past the end: zero rows and NO `total`.
      fireEvent.click(screen.getByTestId("coord-questions-pending-last"));
      await act(async () => {
        await vi.advanceTimersByTimeAsync(0);
      });
      total = 0;

      // Every pending read from here is the TIMER's.
      get.mockClear();
      await act(async () => {
        await vi.advanceTimersByTimeAsync(POLL_INTERVAL_MS);
      });
      await act(async () => {
        await vi.advanceTimersByTimeAsync(0);
      });

      const pendingCalls = get.mock.calls.filter((c) =>
        String(c[0]).includes("/pending?limit=")
      );
      // The detecting read AND the clamp's follow-up.
      expect(pendingCalls.length).toBeGreaterThan(1);
      for (const call of pendingCalls) {
        expect(call[1]).toEqual({ maxRetries: 0 });
      }
    } finally {
      vi.useRealTimers();
    }
  });

  it("jumps to the last page rather than walking 474 of them", async () => {
    // Why an offset pager and not the notifications page's cursor walk: the
    // row an operator cannot find is usually the OLDEST one.
    servePaged(23700);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await screen.findByTestId("coord-questions-pending-range");
    await user.click(screen.getByTestId("coord-questions-pending-last"));

    await waitFor(() => expect(requestedParam("offset", "23650")).toBe(true));
    await waitFor(() =>
      expect(
        screen.getByTestId("coord-questions-pending-range")
      ).toHaveTextContent("23,651–23,700 of 23,700")
    );

    // …and the LAST page says nothing remains, because nothing does.
    //
    // This assertion is the pin on finding 2. `pendingHasMore` carried no
    // `offset` term at all and consulted coord's own offset-aware `truncated`
    // ONLY when `total` was null — i.e. never against a modern build — so the
    // server's correct answer was fetched and discarded. At the end of this
    // very walk the amber banner rendered *"Showing 23,651–23,700 of 23,700 —
    // 23,650 are not on this page"*: 23,650 is the count already paged PAST,
    // printed under a heading that reads "more remain". The old test drove
    // exactly this state and asserted only the range string, so the bug
    // shipped green.
    expect(
      screen.queryByTestId("coord-questions-pending-truncated")
    ).toBeNull();
    expect(document.body.textContent ?? "").not.toMatch(/are not on this page/);
    // The "Next"/"Last page" controls are spent too.
    expect(screen.getByTestId("coord-questions-pending-next")).toBeDisabled();
    expect(screen.getByTestId("coord-questions-pending-last")).toBeDisabled();
  });

  it("counts the rows BEYOND the window, not the ones already walked past", async () => {
    // The same arithmetic one page in, where the two spellings differ by the
    // offset: at rows 51–100 of 23,700 there are 23,600 beyond this window.
    // `total - onPage` would say 23,650 — the 50 on screen subtracted from the
    // queue, with the 50 already passed counted as still to come.
    servePaged(23700);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await screen.findByTestId("coord-questions-pending-range");
    expect(
      screen.getByTestId("coord-questions-pending-truncated")
    ).toHaveTextContent(/23,650 are not on this page/);

    await user.click(screen.getByTestId("coord-questions-pending-next"));
    await waitFor(() =>
      expect(
        screen.getByTestId("coord-questions-pending-range")
      ).toHaveTextContent("51–100 of 23,700")
    );
    const notice = screen.getByTestId("coord-questions-pending-truncated");
    expect(notice).toHaveTextContent(/Showing 51–100 of 23,700/);
    expect(notice).toHaveTextContent(/23,600 are not on this page/);
    expect(notice.textContent ?? "").not.toMatch(/23,650 are not on this page/);
  });

  it("prefers coord's offset-aware `truncated` over a total it could recompute", async () => {
    // Both fields present and DISAGREEING with the page's own arithmetic: the
    // server has already applied `total > effective_offset + shown` and is the
    // authority on its own match set. A page that recomputed would announce
    // more rows on a window coord has said is the end of the walk.
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit="))
        return envelope(rows(50, 23650), {
          total: 23700,
          truncated: false,
          limit: 50,
          offset: 23650,
        });
      return { questions: [] };
    });
    render(<CoordQuestionsPage />);

    await waitFor(() =>
      expect(
        screen.getByTestId("coord-questions-pending-count")
      ).toHaveTextContent("23,700 pending")
    );
    expect(
      screen.queryByTestId("coord-questions-pending-truncated")
    ).toBeNull();
  });

  it("defaults the pending read to audience=operator, and can clear it", async () => {
    // The change the operator actually feels: ~23,700 rows become ~442.
    servePaged(442);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await waitFor(() =>
      expect(requestedParam("audience", "operator")).toBe(true)
    );

    get.mockClear();
    servePaged(23700, 50, "agent");
    await user.click(screen.getByTestId("coord-questions-audience-all"));

    await waitFor(() => {
      const pendingCalls = get.mock.calls
        .map((c) => String(c[0]))
        .filter((u) => u.includes("/pending?limit="));
      expect(pendingCalls.length).toBeGreaterThan(0);
      expect(pendingCalls.every((u) => !u.includes("audience="))).toBe(true);
    });
  });

  it("still renders when the backend IGNORES the audience parameter", async () => {
    // Coord's own `PendingQuery` does not parse `audience` yet (read
    // 2026-09-22) and serde DROPS an unknown key rather than refusing it — so a
    // 200 is not evidence the filter applied. The page must render the rows it
    // got AND say the filter did not take, rather than break or lie.
    servePaged(23700, 50, "agent");
    render(<CoordQuestionsPage />);

    await waitFor(() =>
      expect(
        screen.getByTestId("coord-questions-pending-count")
      ).toHaveTextContent("23,700 pending")
    );
    // Rows still render — degradation is a disclosure, not a failure.
    expect(screen.getAllByTestId("coord-question-card").length).toBe(50);
    expect(
      screen.getByTestId("coord-questions-audience-ignored")
    ).toHaveTextContent(/filter is NOT being applied/i);
  });

  it("says so when a later page does not echo the offset it was asked for", async () => {
    // The `offset`-ignored shape, same class as the audience one — and read
    // off the ECHO, which every build that honours the parameter sends back.
    //
    // The first-row-id heuristic this replaced compared page 2's first row to
    // page 1's, and raced in both directions on the ordinary 10s poll. The
    // echo is a property of THIS response: unambiguous, and free.
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit="))
        // A build with no `offset` field: it serves page 1 forever and, having
        // never heard of the parameter, echoes nothing.
        return envelope(rows(50), {
          total: 23700,
          truncated: true,
          omitOffset: true,
        });
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await screen.findByTestId("coord-questions-pending-range");
    expect(screen.queryByTestId("coord-questions-offset-ignored")).toBeNull();

    await user.click(screen.getByTestId("coord-questions-pending-next"));
    expect(
      await screen.findByTestId("coord-questions-offset-ignored")
    ).toHaveTextContent(/`offset` is being ignored/);
  });

  it("does not cry 'paging is not working' when the rows merely repeat an id", async () => {
    // The FALSE POSITIVE the id heuristic produced, and it is ordinary rather
    // than exotic: the offset IS honoured, but between the two reads the top
    // rows got answered, so page 2 legitimately begins at the id page 1
    // started with. The old page then showed a RED "paging is not working"
    // banner over a pager that was working perfectly.
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit=")) {
        const offset = offsetOf(url);
        // Same row ids at both offsets — but the offset is echoed, which is
        // the only evidence that matters.
        return envelope(rows(50, 0), {
          total: 23700,
          truncated: true,
          offset,
        });
      }
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await screen.findByTestId("coord-questions-pending-range");
    await user.click(screen.getByTestId("coord-questions-pending-next"));

    await waitFor(() => expect(requestedParam("offset", "50")).toBe(true));
    expect(screen.queryByTestId("coord-questions-offset-ignored")).toBeNull();
  });

  it("still warns when the offset went nowhere but a new question changed the ids", async () => {
    // The FALSE NEGATIVE, the dangerous half: `offset` really is being
    // dropped, but a question arrived between the reads, so the first ids
    // differ and the id heuristic stayed silent — page 2 silently equalled
    // page 1 with nothing saying so.
    let generation = 0;
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit=")) {
        generation += 1;
        // Different ids every read, and never an offset echo.
        return envelope(rows(50, generation * 1000), {
          total: 23700,
          truncated: true,
          omitOffset: true,
        });
      }
      return { questions: [] };
    });
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await screen.findByTestId("coord-questions-pending-range");
    await user.click(screen.getByTestId("coord-questions-pending-next"));

    expect(
      await screen.findByTestId("coord-questions-offset-ignored")
    ).toHaveTextContent(/`offset` is being ignored/);
  });

  it("says so when coord answers with a page size it was not asked for", async () => {
    get.mockImplementation(async (url: string) => {
      if (url.includes("gap=true")) return { questions: [] };
      if (url.includes("/pending?limit="))
        // The pre-change coord: our `limit=50` never arrived, so it applied
        // its own default of 100.
        return envelope(rows(100), { total: 23700, limit: 100 });
      return { questions: [] };
    });
    render(<CoordQuestionsPage />);

    expect(
      await screen.findByTestId("coord-questions-pagesize-ignored")
    ).toHaveTextContent(/did not accept the requested page size of 50/);
  });

  it("filters the rows on the page, and states that the filter stops there", async () => {
    servePaged(23700);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await screen.findByTestId("coord-questions-pending-range");
    expect(screen.getAllByTestId("coord-question-card").length).toBe(50);

    await user.type(
      screen.getByTestId("coord-questions-query"),
      "question number 7"
    );

    await waitFor(() =>
      expect(screen.getAllByTestId("coord-question-card").length).toBe(1)
    );
    // The reach of the filter is stated: 23,700 rows exist, 50 are here, and
    // the box searched the 50. Silently searching one page of 23,700 is the
    // same defect this plan is closing, wearing a text box.
    const scope = screen.getByTestId("coord-questions-query-scope");
    expect(scope).toHaveTextContent(/Showing 1 of the 50 rows on this page/);
    expect(scope).toHaveTextContent(
      /never leaves the page you are looking at/i
    );
    // The badge still reports the QUEUE, not the filtered view.
    expect(
      screen.getByTestId("coord-questions-pending-count")
    ).toHaveTextContent("23,700 pending");
  });

  it("does not claim 'No pending questions' when a filter hid them all", async () => {
    servePaged(3);
    const user = userEvent.setup();
    render(<CoordQuestionsPage />);

    await waitFor(() =>
      expect(screen.getAllByTestId("coord-question-card").length).toBe(3)
    );
    await user.type(screen.getByTestId("coord-questions-query"), "zzzz");

    expect(
      await screen.findByTestId("coord-questions-pending-filtered-out")
    ).toHaveTextContent(/None of the 3 rows on this page match/);
    expect(screen.queryByTestId("coord-questions-pending-empty")).toBeNull();
  });

  /**
   * A window PAST THE END of the queue is not an empty queue.
   *
   * The measured shape: the operator pages deep into the agent tier (offset
   * 23,200 of 23,258), agents answer 58 rows, and the next 10s poll's window
   * lands past the end of the match set. Coord's `total` is a
   * `COUNT(*) OVER ()` riding on the returned rows, so there is no row to carry
   * it and coord OMITS the key. `total ?? page.length` then collapsed to 0, the
   * strip went GREEN, and the headline read **"No agent is waiting on an
   * answer"** with ~23,200 still pending — the one sentence this file's own
   * comment says must never render falsely.
   *
   * And there was no way back on screen: the pager is gated on
   * `pendingTotal > pageSize` (0 > 50 → gone) and the truncation notice on
   * `pendingHasMore` (gone), while `pendingOffset` stayed put, so every later
   * poll repainted the same all-clear. The read SUCCEEDED, so `pendingUnknown`
   * and `pendingStale` are both false and neither could catch it.
   */
  describe("a window past the end of the queue", () => {
    /** `servePaged`, but the clamp's re-read at offset 0 never lands. */
    function servePagedHoldingFirstPage(totalOf: () => number, pageSize = 50) {
      let hold = false;
      const never = new Promise<never>(() => {});
      get.mockImplementation(async (url: string) => {
        if (url.includes("gap=true")) return { questions: [] };
        if (url.includes("/pending?limit=")) {
          const offset = offsetOf(url);
          if (offset === 0 && hold) await never;
          const t = totalOf();
          const n = Math.max(0, Math.min(pageSize, t - offset));
          return envelope(rows(n, offset), {
            total: t,
            limit: pageSize,
            offset,
            omitTotal: n === 0 && offset > 0,
          });
        }
        return { questions: [] };
      });
      return {
        hold: () => {
          hold = true;
        },
      };
    }

    it("never renders the all-clear on a window past the end of the queue", async () => {
      let total = 23700;
      const server = servePagedHoldingFirstPage(() => total);
      const user = userEvent.setup();
      render(<CoordQuestionsPage />);

      await screen.findByTestId("coord-questions-pending-range");
      await user.click(screen.getByTestId("coord-questions-pending-last"));
      await waitFor(() => expect(requestedParam("offset", "23650")).toBe(true));

      // The queue shrinks under the page the operator is holding.
      total = 23600;
      server.hold();
      await user.click(screen.getByTestId("coord-questions-refresh"));

      const strip = screen.getByTestId("coord-questions-health");
      await waitFor(() =>
        expect(strip).toHaveAttribute("data-health-level", "amber")
      );
      // THE sentence. Its absence is the whole point of the state.
      expect(strip.textContent ?? "").not.toMatch(
        /No agent is waiting on an answer/i
      );
      expect(strip).toHaveTextContent(
        /past the end of the pending queue — how many agents are waiting is unknown, not zero/i
      );
      // The count is a dash, not the 0 that `total ?? page.length` produced.
      expect(strip).toHaveTextContent(/–\s*pending/);
      expect(strip.textContent ?? "").not.toMatch(/0\s*pending/);
      expect(
        screen.getByTestId("coord-questions-tab-pending")
      ).toHaveTextContent("–");

      // The list slot says the same thing, and the plain empty copy is gone.
      const empty = screen.getByTestId(
        "coord-questions-pending-past-end-empty"
      );
      expect(empty).toHaveTextContent(/past the end of the queue/i);
      expect(empty).toHaveTextContent(/unknown/i);
      expect(screen.queryByTestId("coord-questions-pending-empty")).toBeNull();

      // …and there IS a way back on screen, which this state used to have
      // none of: both the pager and the truncation notice are gated on fields
      // coord withheld here.
      const notice = screen.getByTestId("coord-questions-pending-past-end");
      expect(notice).toHaveTextContent(/Row 23,651 is past the end/);
      expect(
        screen.getByTestId("coord-questions-pending-past-end-reset")
      ).toBeEnabled();
    });

    it("clamps back to the first page and re-reads, so a real total returns", async () => {
      let total = 23700;
      servePaged(() => total);
      const user = userEvent.setup();
      render(<CoordQuestionsPage />);

      await screen.findByTestId("coord-questions-pending-range");
      await user.click(screen.getByTestId("coord-questions-pending-last"));
      await waitFor(() =>
        expect(
          screen.getByTestId("coord-questions-pending-range")
        ).toHaveTextContent("23,651–23,700 of 23,700")
      );

      total = 23600;
      get.mockClear();
      await user.click(screen.getByTestId("coord-questions-refresh"));

      // The clamp re-read is issued at offset 0 — the URL carries no `offset`
      // at all there — and its answer restores a real count immediately.
      await waitFor(() => {
        const pendingCalls = get.mock.calls
          .map((c) => String(c[0]))
          .filter((u) => u.includes("/pending?limit="));
        expect(pendingCalls.some((u) => !u.includes("offset="))).toBe(true);
      });
      await waitFor(() =>
        expect(
          screen.getByTestId("coord-questions-pending-count")
        ).toHaveTextContent("23,600 pending")
      );
      expect(
        screen.getByTestId("coord-questions-pending-range")
      ).toHaveTextContent("1–50 of 23,600");

      // The notice SURVIVES the clamp's own re-read, because otherwise the
      // page would simply snap back to page 1 with no explanation.
      const notice = screen.getByTestId("coord-questions-pending-past-end");
      expect(notice).toHaveTextContent(/Row 23,651 is past the end/);
      expect(notice).toHaveTextContent(/returned to the first page/i);

      // A deliberate navigation retires it.
      await user.click(screen.getByTestId("coord-questions-pending-next"));
      await waitFor(() =>
        expect(
          screen.queryByTestId("coord-questions-pending-past-end")
        ).toBeNull()
      );
    });

    it("keeps a genuine zero at offset 0 as a zero, not as past-the-end", async () => {
      // The other half of the pin. `total: 0` AT OFFSET 0 is a fact — position
      // zero of an empty match set is the whole of it — and must still render
      // the all-clear, or the fix would be indistinguishable from breaking it.
      servePaged(0);
      render(<CoordQuestionsPage />);

      const strip = await screen.findByTestId("coord-questions-health");
      await waitFor(() =>
        expect(strip).toHaveTextContent(/No agent is waiting on an answer/i)
      );
      expect(strip).toHaveAttribute("data-health-level", "green");
      expect(strip).toHaveTextContent(/0\s*pending/);
      expect(
        screen.queryByTestId("coord-questions-pending-past-end")
      ).toBeNull();
      expect(
        screen.getByTestId("coord-questions-pending-empty")
      ).toBeInTheDocument();
    });
  });

  /**
   * The gap queue is the third count on this page, and it was the last one
   * still silently reporting a page length as the alarm.
   *
   * `fetchGaps` fetched `/pending?gap=true` with NO limit, so coord applied its
   * default of 100 — and `blockingGaps` off that page drives the strip level
   * and the "N policy gaps still blocking" headline, with no truncation notice
   * anywhere on the tab. Pre-existing, but in the file whose whole purpose is
   * retiring exactly that.
   */
  describe("the gap queue states its own size", () => {
    function gapRows(n: number) {
      return Array.from({ length: n }, (_, i) => ({
        question_id: `00000000-0000-0000-0000-0000000g${String(i).padStart(
          4,
          "0"
        )}`,
        agent_id: "01a01de1-9d08-7c31-a055-271ad6df6217",
        question: `POLICY_GAP: no clause covers case ${i}`,
        created_at: "2026-09-12T09:00:00Z",
        context:
          'POLICY_GAP {"policy_gap":{"category":"dependencies"},"context":null}',
      }));
    }

    function serveGaps(shown: number, total: number) {
      get.mockImplementation(async (url: string) => {
        if (url.includes("/pending?gap=true"))
          return envelope(gapRows(shown), {
            total,
            limit: 200,
            offset: 0,
          });
        if (url.includes("/answered?gap=true"))
          return envelope([], { total: 0, limit: 200, offset: 0 });
        if (url.includes("/pending?limit="))
          return envelope([], { total: 0, limit: 50, offset: 0 });
        return { questions: [] };
      });
    }

    it("bounds the gap read explicitly instead of taking coord's default", async () => {
      serveGaps(200, 640);
      render(<CoordQuestionsPage />);

      await waitFor(() =>
        expect(requestedUrl("/pending?gap=true&limit=200")).toBe(true)
      );
    });

    it("says the blocking count is AT LEAST N when the gap read was cut short", async () => {
      serveGaps(200, 640);
      const user = userEvent.setup();
      render(<CoordQuestionsPage />);

      const strip = await screen.findByTestId("coord-questions-health");
      // The headline is the surface an operator reads first, and an exact "200
      // policy gaps still blocking" off a capped page under-reports the alarm
      // by 440.
      await waitFor(() =>
        expect(strip).toHaveTextContent(
          /At least 200 policy gaps still blocking/
        )
      );

      await user.click(screen.getByTestId("coord-questions-tab-gaps"));
      const notice = await screen.findByTestId(
        "coord-questions-gaps-truncated"
      );
      expect(notice).toHaveTextContent(/cut the gap queue short at 200 rows/i);
      expect(notice).toHaveTextContent(/640 unanswered gap questions exist/);
      expect(notice).toHaveTextContent(/AT LEAST 200, not exactly it/);
    });

    it("shows no gap truncation notice when the gap queue fits on the page", async () => {
      // The other half of the pin: a notice that always renders proves nothing.
      serveGaps(3, 3);
      const user = userEvent.setup();
      render(<CoordQuestionsPage />);

      const strip = await screen.findByTestId("coord-questions-health");
      await waitFor(() =>
        expect(strip).toHaveTextContent(/3 policy gaps still blocking/)
      );
      expect(strip.textContent ?? "").not.toMatch(/At least/);

      await user.click(screen.getByTestId("coord-questions-tab-gaps"));
      await screen.findByTestId("coord-questions-gaps-list");
      expect(screen.queryByTestId("coord-questions-gaps-truncated")).toBeNull();
    });
  });

  it("names the refresh control instead of shipping an unlabelled icon", async () => {
    // §6.4 — `RefreshButton` exists because 18 of the 28 coord pages rendering
    // a `RefreshCw` carried no accessible name at all. This page was one.
    servePaged(3);
    render(<CoordQuestionsPage />);

    const refresh = await screen.findByTestId("coord-questions-refresh");
    expect(refresh).toHaveAttribute("aria-label", "Refresh agent questions");
    expect(refresh.getAttribute("title") ?? "").toMatch(/every 10 s/);
    expect(screen.getByLabelText("Refresh agent questions")).toBe(refresh);
  });
});
